<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Printer } from '@element-plus/icons-vue'
import { api, messageOf } from '../api'

const route=useRoute();const router=useRouter();const report=ref<any>(null);const loading=ref(true);const error=ref('')
const optionLabels:Record<string,string>={OFTEN:'经常观察到',SOMETIMES:'偶尔观察到',NOT_SEEN_THIS_TIME:'本次未观察到',UNABLE_TO_JUDGE:'无法判断',NOT_OBSERVED:'未观察'}
function percent(value:number|null){return value==null?'未获得有效检测数据':`${Math.round(value*100)}%`}
function formatDate(value:string|null){return value||'未限定'}
async function load(){loading.value=true;error.value='';report.value=null;try{const childId=Number(route.params.childId);if(!Number.isInteger(childId)||childId<1)throw new Error('儿童档案参数不正确');report.value=(await api.get(`/children/${childId}/report`,{params:{start_date:route.query.start||undefined,end_date:route.query.end||undefined,record_types:route.query.types||undefined}})).data}catch(reason){error.value=messageOf(reason)}finally{loading.value=false}}
function printReport(){if(report.value&&!loading.value&&!error.value)window.print()}
onMounted(load)
</script>

<template>
  <div class="report-actions no-print"><el-button @click="router.push({path:'/history',query:{child:String(route.params.childId)}})">返回综合历史</el-button><el-button type="primary" :icon="Printer" :disabled="!report||loading||!!error" @click="printReport">打印 / 保存为 PDF</el-button></div>
  <el-alert v-if="error" class="no-print" :title="error" type="error" show-icon :closable="false"><template #default><el-button link type="primary" @click="load">重新加载</el-button></template></el-alert>
  <div v-loading="loading" class="report-stage">
    <article v-if="report" class="report-paper">
      <header><h1>{{ report.title }}</h1><p>报告编号：R-{{ report.child.child_code }}-{{ report.generated_at.slice(0,10).replaceAll('-','') }}</p></header>
      <section><h2>一、基本信息</h2><table><tbody><tr><th>儿童编号</th><td>{{ report.child.child_code }}</td><th>档案昵称</th><td>{{ report.child.nickname }}</td></tr><tr><th>年龄</th><td>{{ report.child.age_text }}</td><th>性别</th><td>{{ report.child.gender||'未填写' }}</td></tr><tr><th>建档日期</th><td>{{ report.child.created_at.slice(0,10) }}</td><th>报告生成日期</th><td>{{ report.generated_at.slice(0,10) }}</td></tr><tr><th>统计时间范围</th><td colspan="3">{{ formatDate(report.requested_range.start_date) }} 至 {{ formatDate(report.requested_range.end_date) }}</td></tr></tbody></table></section>
      <section><h2>二、记录概览</h2><div class="count-grid"><div><b>{{ report.counts.video }}</b><span>视频分析</span></div><div><b>{{ report.counts.observation }}</b><span>行为观察</span></div><div><b>{{ report.counts.activity }}</b><span>家庭互动</span></div></div><p>实际记录范围：{{ formatDate(report.actual_range.start_date) }} 至 {{ formatDate(report.actual_range.end_date) }}。<template v-if="report.truncated">记录较多，本报告仅纳入最近 {{ report.record_limit }} 条。</template></p></section>
      <section v-if="report.included_types.includes('VIDEO')"><h2>三、视频分析摘要</h2><div v-if="!report.videos.length" class="empty-section">暂无相关记录</div><div v-for="item in report.videos" :key="item.id" class="record-block"><h3>{{ item.analysis_date }} · {{ item.video_name }}</h3><table><tbody><tr><th>状态</th><td>{{ item.status_label }}</td><th>视频时长</th><td>{{ item.duration_seconds.toFixed(1) }} 秒</td></tr><tr><th>采样帧数</th><td>{{ item.sampled_frames??'未生成' }}</td><th>数据质量</th><td>{{ item.quality_level||'未生成' }}</td></tr><tr><th>姿态检测覆盖率</th><td>{{ percent(item.pose_coverage) }}</td><th>面部检测覆盖率</th><td>{{ percent(item.face_coverage) }}</td></tr></tbody></table><p v-if="item.status!=='COMPLETED'">该任务未形成完整分析结果：{{ item.error_message||item.status_label }}。</p><p class="note">检测覆盖率只描述通用视觉模型在画面中的检测情况，不代表儿童健康程度。</p></div></section>
      <section v-if="report.included_types.includes('OBSERVATION')"><h2>四、行为观察记录</h2><div v-if="!report.observations.length" class="empty-section">暂无相关记录</div><div v-for="item in report.observations" :key="item.id" class="record-block"><h3>{{ item.observation_date }} · {{ item.observation_scene }}</h3><p><b>观察者：</b>{{ item.observer_role }}</p><table><tbody><tr v-for="entry in item.observation_items" :key="entry.key"><th>{{ entry.dimension_label }}</th><td>{{ entry.label }}</td><td colspan="2">{{ optionLabels[entry.value]||entry.value_label }}</td></tr></tbody></table><p><b>辅助观察摘要：</b>{{ item.auxiliary_summary }}</p><p><b>补充备注：</b>{{ item.summary_notes||'未填写' }}</p></div></section>
      <section v-if="report.included_types.includes('ACTIVITY')"><h2>五、家庭互动活动记录</h2><div v-if="!report.activities.length" class="empty-section">暂无相关记录</div><div v-for="item in report.activities" :key="item.id" class="record-block"><h3>{{ item.activity_date }} · {{ item.activity_name }}</h3><table><tbody><tr><th>活动分类</th><td>{{ item.activity_category }}</td><th>完成情况</th><td>{{ item.completion_label }}</td></tr><tr><th>实际时长</th><td>{{ item.actual_duration_minutes==null?'未填写':`${item.actual_duration_minutes} 分钟` }}</td><th>建议时长快照</th><td>{{ item.suggested_duration_minutes }} 分钟</td></tr></tbody></table><p><b>参与反馈：</b>{{ item.child_response||'未填写' }}</p><p><b>备注：</b>{{ item.notes||'未填写' }}</p></div></section>
      <section><h2>六、记录整理说明</h2><ul><li v-for="line in report.record_explanation" :key="line">{{ line }}</li></ul></section>
      <section class="disclaimer"><h2>七、使用说明</h2><p>{{ report.disclaimer }}</p></section>
      <footer>本报告数据来源于当前本地系统数据库 · 生成日期 {{ report.generated_at.slice(0,10) }}</footer>
    </article>
  </div>
</template>

<style scoped>
.report-actions{display:flex;justify-content:space-between;margin-bottom:18px}.report-stage{min-height:400px}.report-paper{width:min(210mm,100%);min-height:297mm;box-sizing:border-box;margin:0 auto 30px;background:#fff;color:#262b2d;padding:18mm 17mm;box-shadow:0 8px 30px rgba(35,60,63,.1);font-family:"Microsoft YaHei","Noto Sans CJK SC",sans-serif;font-size:12px;line-height:1.7}.report-paper>header{text-align:center;border-bottom:2px solid #314f52;padding-bottom:14px;margin-bottom:22px}.report-paper h1{font-size:24px;margin:0 0 8px}.report-paper header p,.note{color:#667477}.report-paper section{margin:0 0 22px;break-inside:auto}.report-paper h2{font-size:16px;border-left:4px solid #356f72;padding-left:9px;margin:0 0 12px;break-after:avoid}.report-paper h3{font-size:13px;margin:0 0 9px;break-after:avoid}.report-paper table{width:100%;border-collapse:collapse;table-layout:fixed}.report-paper tr{break-inside:avoid}.report-paper th,.report-paper td{border:1px solid #cfd7d8;padding:7px 9px;text-align:left;vertical-align:top;word-break:break-word}.report-paper th{width:18%;background:#f1f5f5;font-weight:600}.count-grid{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #cfd7d8}.count-grid div{text-align:center;padding:12px;border-right:1px solid #cfd7d8}.count-grid div:last-child{border:0}.count-grid b,.count-grid span{display:block}.count-grid b{font-size:22px;color:#315f62}.record-block{border:1px solid #d8dfe0;padding:12px;margin-bottom:10px;break-inside:avoid}.record-block p{white-space:pre-wrap}.empty-section{padding:15px;border:1px dashed #ccd5d6;color:#748286;text-align:center}.disclaimer{background:#f4f6f6;padding:12px 14px;break-inside:avoid}.report-paper footer{text-align:center;border-top:1px solid #ccd4d5;padding-top:10px;color:#778487;font-size:10px}.report-paper ul{padding-left:20px}
</style>
<style>
@media print{@page{size:A4 portrait;margin:14mm}.shell>aside,.workspace>header,.no-print{display:none!important}.shell,.workspace{display:block!important;margin:0!important;min-height:0!important}.workspace main{padding:0!important;max-width:none!important}.report-stage{min-height:0!important}.report-paper{width:auto!important;min-height:0!important;margin:0!important;padding:0!important;box-shadow:none!important;font-size:10.5pt!important;color:#000!important}.report-paper h1{font-size:20pt!important}.report-paper h2{font-size:13pt!important}.report-paper h3{font-size:11pt!important}body{background:#fff!important;-webkit-print-color-adjust:exact;print-color-adjust:exact}}
</style>
